glv = dict()
glv_size = 50
try:
    with open('data/glove.6B.50d.txt','r', encoding='utf-8', errors='ignore') as fp:
        line_count = 0
        for line in fp:
            parts = line.strip().split()
            if len(parts) < 2:
                continue
            try:
                word = parts[0]
                vec = list(map(float, parts[1:]))
                if len(vec) != glv_size:
                    continue
                glv[word] = vec
                line_count += 1
                if line_count % 1000 == 0:
                    print(f"Loaded {line_count} words...")
            except ValueError:
                continue
except Exception as e:
    print(f"Error: {e}")
print(f"Total valid embeddings loaded: {len(glv)}")"}

